using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;
[InitializeOnLoad]public static class ObjectiveTrailReview {
 const string E="Evidence/objective-trails-20261030/";
 static List<Vector3[]> routes=new List<Vector3[]>();static StringBuilder report=new StringBuilder();
 static ObjectiveTrailReview(){EditorApplication.delayCall+=Build;EditorApplication.delayCall+=Refine;EditorApplication.delayCall+=OpenSightline;}
 static void Refine(){if(EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(E+"built.txt")||File.Exists(E+"sightline.txt"))return;var fade=Object.FindObjectOfType<SettlementVegetationFade>();if(!fade||!fade.gameObject.scene.name.Contains("HunterTrails"))return;fade.occludedVisibility=.055f;EditorUtility.SetDirty(fade);EditorSceneManager.SaveScene(fade.gameObject.scene);File.WriteAllText(E+"sightline.txt","Copied-scene vegetation camera occlusion visibility .18 -> .055; forest and lights retained.");}
 static void OpenSightline(){if(EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(E+"sightline.txt")||File.Exists(E+"canopy-spacing.txt"))return;var player=Object.FindObjectOfType<HunterTorchPose>();if(!player||!player.gameObject.scene.name.Contains("HunterTrails"))return;var point=Object.FindObjectsOfType<DemoInteractable>().First(t=>t.clueId=="trail").transform.position;var camera=player.GetComponent<DemoMovement>().viewCamera;var offset=camera.GetComponent<DemoCamera>().offset;var origin=point+offset;var end=point+Vector3.up*.9f;var ray=new Ray(origin,(end-origin).normalized);float distance=Vector3.Distance(origin,end);var text=new StringBuilder();var terrain=Object.FindObjectOfType<Terrain>();foreach(Transform tree in GameObject.Find("Forest").transform){var rs=tree.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);if(b.size.y<4)continue;float hit;if(!b.Contains(origin)&&(!b.IntersectRay(ray,out hit)||hit>distance))continue;float side=b.center.x<point.x?-1:1;float dx=point.x+side*(b.extents.x+1.1f)-b.center.x;var p=tree.position;p.x+=dx;p.y=terrain.SampleHeight(p)+terrain.transform.position.y;tree.position=p;text.AppendLine(tree.name+" shifted sideways="+dx.ToString("F2"));}EditorSceneManager.SaveScene(player.gameObject.scene);File.WriteAllText(E+"canopy-spacing.txt",text.ToString());}
 static Vector3 Sample(Vector3 p){if(NavMesh.SamplePosition(p,out var h,3,NavMesh.AllAreas))return h.position;throw new System.Exception("No navigation near "+p);}
 static Vector3[] Route(Vector3 from,Vector3 to){var p=new NavMeshPath();var a=Sample(from);var b=Sample(to);bool ok=NavMesh.CalculatePath(a,b,NavMesh.AllAreas,p)&&p.status==NavMeshPathStatus.PathComplete;report.AppendLine("path "+a+" -> "+b+" complete="+ok);if(!ok)throw new System.Exception("Trail path incomplete");routes.Add(p.corners);return p.corners;}
 static float Dist(Vector3 p){float d=float.MaxValue;foreach(var line in routes)for(int j=1;j<line.Length;j++){var a=line[j-1];var b=line[j];a.y=b.y=p.y=0;var t=Mathf.Clamp01(Vector3.Dot(p-a,b-a)/(b-a).sqrMagnitude);d=Mathf.Min(d,Vector3.Distance(p,Vector3.Lerp(a,b,t)));}return d;}
 static Vector3 Nearest(Vector3 p){Vector3 best=Vector3.zero;float d=float.MaxValue;foreach(var line in routes)for(int j=1;j<line.Length;j++){var a=line[j-1];var b=line[j];a.y=b.y=p.y=0;var q=Vector3.Lerp(a,b,Mathf.Clamp01(Vector3.Dot(p-a,b-a)/(b-a).sqrMagnitude));if((q-p).sqrMagnitude<d){d=(q-p).sqrMagnitude;best=q;}}return Sample(best);}
 static void Build(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists(E+"built.txt"))return;Directory.CreateDirectory(E);var scene=EditorSceneManager.OpenScene("Assets/Demo/Scenes/PrologueSettlement_HunterTorch.unity");string path=AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Scenes/PrologueSettlement_HunterTrails.unity");EditorSceneManager.SaveScene(scene,path);var player=Object.FindObjectOfType<HunterTorchPose>();var flow=player.GetComponent<DemoPrologueFlow>();routes.Clear();report.Clear();
 Vector3[] trunk={player.transform.position,new Vector3(-32,0,-6.2f),new Vector3(-20,0,-7.4f),new Vector3(-8,0,-7.2f),new Vector3(-2,0,-6.4f),new Vector3(10,0,-5),new Vector3(20,0,-4.2f),new Vector3(28,0,-2.6f),new Vector3(32,0,-.8f),new Vector3(36,0,-1.6f),new Vector3(40,0,-3.4f),new Vector3(44,0,-5.2f),new Vector3(48,0,-6.8f),new Vector3(52,0,-8.1f),new Vector3(56,0,-9.2f)};
 for(int i=1;i<trunk.Length;i++)Route(trunk[i-1],trunk[i]);var stops=new List<ObjectiveTrailProbe.Stop>();foreach(var clue in Resources.FindObjectsOfTypeAll<DemoInteractable>().Where(x=>x.gameObject.scene==scene)){var end=Sample(clue.transform.position);var start=Nearest(end);var branch=Route(start,end);var approach=branch.Length>1?Vector3.MoveTowards(end,branch[branch.Length-2],3):start;stops.Add(new ObjectiveTrailProbe.Stop{name=clue.clueId,target=end,approach=Sample(approach)});report.AppendLine("objective="+clue.clueId+" pos="+end);}
 foreach(var pair in new[]{(name:"combat",p:flow.enemy.transform.position),(name:"checkpoint",p:flow.checkpoint.position)}){var end=Sample(pair.p);var start=Nearest(end);Route(start,end);stops.Add(new ObjectiveTrailProbe.Stop{name=pair.name,target=end,approach=Sample(Vector3.MoveTowards(end,start,3))});}
 var terrain=Object.FindObjectOfType<Terrain>();var data=Object.Instantiate(terrain.terrainData);string dir="Assets/Demo/Environment/ObjectiveTrails";Directory.CreateDirectory(dir);AssetDatabase.CreateAsset(data,AssetDatabase.GenerateUniqueAssetPath(dir+"/TrailTerrain.asset"));terrain.terrainData=data;terrain.GetComponent<TerrainCollider>().terrainData=data;
 int n=data.alphamapResolution;var map=data.GetAlphamaps(0,0,n,n);int road=System.Array.FindIndex(data.terrainLayers,l=>l.name.Contains("Road"));int forest=0,leaves=3;Vector3 origin=terrain.transform.position;
 for(int y=0;y<n;y++)for(int x=0;x<n;x++){var world=origin+new Vector3((float)x/(n-1)*data.size.x,0,(float)y/(n-1)*data.size.z);float d=Dist(world);if(d>4)continue;float noise=Mathf.PerlinNoise(world.x*.7f+31,world.z*.7f+47);float half=.48f+noise*.13f;float strength=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(half,half+.32f,d)))*.84f;
 if(world.x>-5&&d>half){float old=map[y,x,road];float faded=old*Mathf.Lerp(.13f,1,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(half,half+.5f,d)));float delta=old-faded;map[y,x,road]=faded;map[y,x,leaves]+=delta*.55f;map[y,x,forest]+=delta*.45f;}
 for(int l=0;l<data.alphamapLayers;l++)map[y,x,l]*=1-strength;map[y,x,road]+=strength;}
 data.SetAlphamaps(0,0,map);EditorUtility.SetDirty(data);
 int hidden=0;var f=GameObject.Find("Forest");if(f)foreach(Transform t in f.transform){string name=t.name.ToLowerInvariant();if(!new[]{"grass","fern","bush","mugwort","leaves","shrub","reed","flower"}.Any(k=>name.Contains(k)))continue;var r=t.GetComponentsInChildren<Renderer>();if(r.Length==0)continue;Bounds b=r[0].bounds;foreach(var rr in r)b.Encapsulate(rr.bounds);float radius=Mathf.Min(1.0f,Mathf.Max(b.extents.x,b.extents.z)*.55f);if(Dist(t.position)<.68f+radius){t.gameObject.SetActive(false);hidden++;}}
 var edge=new GameObject("Subtle objective trail edge details").transform;var rng=new System.Random(1030);int rocks=0,fences=0;var placed=new List<Vector3>();foreach(var line in routes)for(int j=1;j<line.Length;j++){Vector3 tangent=(line[j]-line[j-1]).normalized;float length=Vector3.Distance(line[j],line[j-1]);for(float d=2.7f;d<length-1.3f;d+=4.5f+(float)rng.NextDouble()*3){Vector3 p=Vector3.Lerp(line[j-1],line[j],d/length);var side=Vector3.Cross(Vector3.up,tangent);p+=side*(rng.Next(2)==0?-1:1)*(1.1f+(float)rng.NextDouble()*.5f);if(placed.Any(q=>Vector3.Distance(p,q)<3)||Dist(p)<.95f)continue;placed.Add(p);bool fence=rng.NextDouble()<.2;string asset=fence?"Assets/Viking Village/Prefabs/Props/pf_fence_01.prefab":"Assets/Polyeler/EssentialNaturePack/Prefabs/Rock_"+(rng.Next(2)==0?"B":"D")+".prefab";var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(asset));go.transform.SetParent(edge);foreach(var t in go.GetComponentsInChildren<Transform>(true)){GameObjectUtility.SetStaticEditorFlags(t.gameObject,0);GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);}foreach(var c in go.GetComponentsInChildren<Collider>())Object.DestroyImmediate(c);go.transform.rotation=Quaternion.Euler(fence?0:rng.Next(-9,10),fence?Quaternion.LookRotation(tangent).eulerAngles.y+85+rng.Next(-15,16):rng.Next(360),fence?rng.Next(-5,6):rng.Next(-8,9));var rs=go.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var rr in rs)b.Encapsulate(rr.bounds);float size=fence?1.35f:.28f+(float)rng.NextDouble()*.32f;go.transform.localScale*=size/Mathf.Max(b.size.x,b.size.z);b=rs[0].bounds;foreach(var rr in rs)b.Encapsulate(rr.bounds);p.y=terrain.SampleHeight(p)+origin.y;go.transform.position+=p-new Vector3(b.center.x,b.min.y+(fence?.05f:.045f),b.center.z);if(fence)fences++;else rocks++;}}
 report.AppendLine("scene="+path+" terrain="+AssetDatabase.GetAssetPath(data)+" hiddenLowPlants="+hidden+" rocks="+rocks+" fenceFragments="+fences+" nominalDirtCore=0.96-1.22m softEdge=.32m");File.WriteAllText(E+"built.txt",report.ToString());var probe=player.gameObject.AddComponent<ObjectiveTrailProbe>();probe.stops=stops.ToArray();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 [MenuItem("Vampire Demo/Finish Objective Trail Review")]static void Finish(){if(EditorApplication.isPlaying)return;var p=Object.FindObjectOfType<ObjectiveTrailProbe>();if(!p)return;var scene=p.gameObject.scene;Object.DestroyImmediate(p);EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene(scene.path);object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(null,counts);File.WriteAllText(E+"saved.txt","Saved and reopened "+scene.path+" probe removed; errors="+counts[0]+" warnings="+counts[1]);}
}
